from scipy.cluster.hierarchy import linkage

def probe():
    x = np.asarray([0, 0, -1], dtype=float)
    try:
        y = linkage(x, method='centroid')
        return {'outcome':'no_error','result':np.asarray(y).tolist()}
    except Exception as e:
        return {'outcome':type(e).__name__,'message':str(e)[:200]}

probe_output = probe()
print(probe_output)

